import { readFileSync } from "node:fs";
import { gunzipSync } from "node:zlib";

// Generated by scratch/build_data.py from the interrupt list, the bundled walkthroughs and the assembler reference (data/).

export interface RegText {
  register: string;
  text: string;
}

export interface Entry {
  /** Entry anchor id, unique, e.g. "213D", "330000", "214402_1" */
  id: string;
  int: string;
  /** Flag letters: U undocumented, u partially documented, C callout, ... */
  flags: string;
  /** AH / AL discriminators derived from the entry id (AX-keyed calls fill both) */
  ah: number | null;
  al: number | null;
  /** additional register discriminators e.g. ["BX0000"] */
  extra: string[];
  category: string;
  title: string;
  regsIn: RegText[];
  regsOut: RegText[];
  /** verbatim `Return:` text, useful when it names no registers ("never returns") */
  ret: string;
  desc: string;
  notes: string;
  seeAlso: string;
  sections: Record<string, string>;
  tables: string;
}

export interface Topic {
  kind: "spec" | "notes";
  title: string;
  text: string;
}

export interface InterruptInfo {
  number: string;
  name: string;
  walkthrough: string;
  reference: Topic[];
}

export interface Supplement {
  walkthrough: string;
  reference: Topic[];
}

export interface InterruptData {
  interrupts: Record<string, InterruptInfo>;
  supplements: Record<string, Supplement>;
  entries: Entry[];
}

/** Interrupts whose functions are selected by the full AX (not AH alone): mouse, DOS multiplex, DPMI. */
export const AX_KEYED_INTS: ReadonlySet<string> = new Set(["2F", "31", "33"]);
/** Function-keyed even where the bundled prose (walkthroughs) has no per-function topics. */
const ALWAYS_KEYED = new Set(["2F", "31", "33", "67"]);

export class InterruptDb {
  readonly byInt = new Map<string, Entry[]>();
  readonly byId = new Map<string, Entry>();

  constructor(readonly data: InterruptData) {
    for (const e of data.entries) {
      let list = this.byInt.get(e.int);
      if (!list) this.byInt.set(e.int, (list = []));
      list.push(e);
      this.byId.set(e.id, e);
    }
  }

  static load(url: URL = new URL("../../data/interrupts.json.gz", import.meta.url)): InterruptDb {
    return new InterruptDb(JSON.parse(gunzipSync(readFileSync(url)).toString("utf8")) as InterruptData);
  }

  info(int: string): InterruptInfo | undefined {
    return this.data.interrupts[int];
  }

  entriesFor(int: string): readonly Entry[] {
    return this.byInt.get(int) ?? [];
  }

  isAxKeyed(int: string): boolean {
    return AX_KEYED_INTS.has(int);
  }

  /** True when the interrupt dispatches on a function register (AH/AX) rather than being a single service. */
  isFunctionKeyed(int: string): boolean {
    if (ALWAYS_KEYED.has(int)) return true;
    const prefix = `${int}:`;
    return Object.keys(this.data.supplements).some((k) => k.startsWith(prefix));
  }

  /**
   * Resource tail ("3D", "44-02", "03") for the curated walkthrough/reference notes covering this entry, if any.
   * AX-keyed interrupts index their notes by AL (the walkthrough "INT 33,3" is AX=0003h).
   */
  supplementFn(e: Entry): string | undefined {
    if (e.ah === null) return undefined;
    const hh = e.ah.toString(16).toUpperCase().padStart(2, "0");
    if (AX_KEYED_INTS.has(e.int)) {
      if (e.ah !== 0 || e.al === null) return undefined;
      const ll = e.al.toString(16).toUpperCase().padStart(2, "0");
      return this.supplement(`${e.int}:${ll}`) ? ll : undefined;
    }
    if (e.al !== null) {
      const ll = e.al.toString(16).toUpperCase().padStart(2, "0");
      if (this.supplement(`${e.int}:${hh}:${ll}`)) return `${hh}-${ll}`;
    }
    return this.supplement(`${e.int}:${hh}`) ? hh : undefined;
  }

  /** key is "21:3D" (interrupt:AH) or "21:44:02" (interrupt:AH:AL) */
  supplement(key: string): Supplement | undefined {
    return this.data.supplements[key];
  }
}

let shared: InterruptDb | undefined;
export function getInterruptDb(): InterruptDb {
  return (shared ??= InterruptDb.load());
}
